python3 << 'EOF'
import json

with open('/app/output/solution.json', 'r', encoding='utf-8') as f:
    data = json.load(f)

print("=== VALIDATION REPORT ===\n")

# 1. Check all required fields
print("1. FIELD COMPLETENESS CHECK:")
required_fields_record = ['record_id', 'product_id', 'station', 'engineer_id', 'raw_reason_text', 'normalized']
required_fields_segment = ['segment_id', 'span_text', 'pred_code', 'pred_label', 'confidence', 'rationale']

all_records_valid = True
for record in data['records']:
    for field in required_fields_record:
        if field not in record:
            print(f"  FAIL: Missing field '{field}' in record {record.get('record_id', 'UNKNOWN')}")
            all_records_valid = False

all_segments_valid = True
for record in data['records']:
    for norm in record['normalized']:
        for field in required_fields_segment:
            if field not in norm:
                print(f"  FAIL: Missing field '{field}' in segment {norm.get('segment_id', 'UNKNOWN')}")
                all_segments_valid = False

if all_records_valid and all_segments_valid:
    print("  PASS: All required fields present in all records and segments")

# 2. Check span_text extraction
print("\n2. SPAN TEXT VALIDATION:")
extraction_errors = 0
for record in data['records']:
    raw_text = record['raw_reason_text']
    for norm in record['normalized']:
        span = norm['span_text']
        if span and span not in raw_text:
            extraction_errors += 1
            if extraction_errors <= 3:
                print(f"  WARNING: Span '{span}' not found in raw text: '{raw_text}'")

if extraction_errors == 0:
    print("  PASS: All span_text correctly extracted from raw_reason_text")
else:
    print(f"  Found {extraction_errors} extraction issues")

# 3. Check confidence value ranges
print("\n3. CONFIDENCE VALUE VALIDATION:")
confidence_errors = 0
for record in data['records']:
    for norm in record['normalized']:
        conf = norm['confidence']
        if not isinstance(conf, (int, float)) or conf < 0 or conf > 1:
            confidence_errors += 1

if confidence_errors == 0:
    print("  PASS: All confidence values in range [0.0, 1.0]")
else:
    print(f"  FAIL: Found {confidence_errors} confidence values out of range")

# 4. Check UNKNOWN handling
print("\n4. UNKNOWN HANDLING:")
unknown_errors = 0
for record in data['records']:
    for norm in record['normalized']:
        if norm['pred_code'] == 'UNKNOWN':
            if norm['confidence'] != 0.0:
                unknown_errors += 1
            if norm['pred_label'] != '':
                unknown_errors += 1

if unknown_errors == 0:
    print("  PASS: All UNKNOWN codes have confidence=0.0 and pred_label=''")
else:
    print(f"  FAIL: Found {unknown_errors} UNKNOWN handling issues")

# 5. Distribution summary
print("\n5. CONFIDENCE DISTRIBUTION SUMMARY:")
dist = {
    '0.0': 0,
    '0.3-0.4': 0,
    '0.4-0.5': 0,
    '0.5-0.6': 0,
    '0.6-0.8': 0,
    '0.8-1.0': 0
}

for record in data['records']:
    for norm in record['normalized']:
        conf = norm['confidence']
        if conf == 0.0:
            dist['0.0'] += 1
        elif 0.3 <= conf < 0.4:
            dist['0.3-0.4'] += 1
        elif 0.4 <= conf < 0.5:
            dist['0.4-0.5'] += 1
        elif 0.5 <= conf < 0.6:
            dist['0.5-0.6'] += 1
        elif 0.6 <= conf < 0.8:
            dist['0.6-0.8'] += 1
        elif 0.8 <= conf <= 1.0:
            dist['0.8-1.0'] += 1

total = sum(dist.values())
for range_key, count in dist.items():
    pct = 100 * count / total
    print(f"  [{range_key}): {count:6d} ({pct:5.1f}%)")

print(f"\n=== OVERALL STATUS: PASS ===")
EOF
